  --color-canvas: #1a1a1a;
  --color-panel: #222222;
  --color-line: #3d3d3d;
  --color-muted: #8f8f8f;
  /* shadcn tokens used by components/chart.tsx */
  --color-background: #222222;
  --color-foreground: #f5f5f5;
  --color-border: #3d3d3d;
  --color-muted-foreground: #8f8f8f;

  --animate-pop: pop 320ms cubic-bezier(0.34, 1.56, 0.64, 1) both;
  --animate-flash: flash 700ms ease-out;
  --animate-vanish: vanish 450ms ease-in forwards;
  --animate-row-in: row-in 800ms ease-out;
  --animate-row-out: row-out 600ms ease-in forwards;
  --animate-grow: grow 600ms cubic-bezier(0.22, 1, 0.36, 1) both;

  @keyframes pop {
    from { opacity: 0; transform: scale(0); }
    to { opacity: 1; transform: scale(1); }
  }
  @keyframes vanish {
    0% { transform: scale(1); }
    35% { transform: scale(1.5); opacity: 1; }
    100% { transform: scale(0); opacity: 0; }
  }
  @keyframes row-in {
    0% { background: rgb(52 211 153 / 0.22); transform: translateY(-6px); opacity: 0; }
    30% { transform: translateY(0); opacity: 1; }
    100% { background: transparent; }
  }
  @keyframes row-out {
    0% { background: rgb(239 68 68 / 0.25); }
    60% { opacity: 1; }
    100% { background: transparent; opacity: 0; }
  }
  @keyframes grow {
    from { transform: scaleX(0); }
  }
  @keyframes flash {
    from { color: var(--color-emerald-300); }
  }
}

:root {
  color-scheme: dark;
}

body {
  @apply bg-canvas text-neutral-200 antialiased;
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
}
